UPDATE fnd01_fund_code
   SET fnd01_fund_cd    = #{r.fundCode},
       fnd01_start_date = #{r.startDate,jdbcType=DATE},
       fnd01_end_date   = #{r.endDate,jdbcType=DATE},
       fnd01_close_yn   = #{r.closeYn},
       fnd01_note       = #{r.note}
 WHERE fnd01_fund_code_id = #{r.fundCodeId}
   AND fnd01_company_id   = #{companyId}
   AND fnd01_plan_yn      = 'false'

UPDATE fnd01_fund_code
   SET fnd01_note = #{note}
 WHERE fnd01_fund_code_id = #{fundCodeId}
   AND fnd01_company_id   = #{companyId}
